"""
Batch robust adaptive denoising for volatile, non-stationary time series.

Returned samples are aligned to input indices window_size - 1 through end.
"""
import numpy as np

try:
    from scipy.signal import butter, sosfiltfilt, savgol_filter
except Exception:
    butter = None
    sosfiltfilt = None
    savgol_filter = None


def _finite_signal(x):
    z = np.asarray(x, dtype=float).reshape(-1).copy()
    if z.size == 0:
        return z
    good = np.isfinite(z)
    if not np.all(good):
        if np.any(good):
            idx = np.arange(z.size)
            z[~good] = np.interp(idx[~good], idx[good], z[good])
        else:
            z.fill(0.0)
    return z


def _odd_at_most(value, n):
    w = min(int(value), int(n))
    return w if w % 2 else w - 1


def _savgol_safe(x, preferred=11):
    x = _finite_signal(x)
    n = len(x)
    if savgol_filter is None or n < 5:
        return x.copy()
    w = _odd_at_most(preferred, n)
    if w < 5:
        return x.copy()
    try:
        return savgol_filter(x, w, min(3, w - 2), mode="interp")
    except Exception:
        return x.copy()


def _median3(x):
    """Symmetric order-statistic preconditioner with endpoint replication."""
    x = _finite_signal(x)
    if len(x) < 3:
        return x.copy()
    p = np.pad(x, (1, 1), mode="edge")
    return np.median(np.vstack((p[:-2], p[1:-1], p[2:])), axis=0)


def _noise_sigma(x):
    if len(x) < 2:
        return 0.0
    d = np.diff(x)
    return float(np.median(np.abs(d - np.median(d))) /
                 (0.67448975 * np.sqrt(2.0)))


def _spectral_cutoff(x):
    """Noise-floor-corrected retained-power cutoff in scipy normalized units."""
    n = len(x)
    if n < 8:
        return 0.18
    power = np.abs(np.fft.rfft(x)) ** 2
    bins = len(power)
    tail = power[max(1, int(0.70 * bins)):]
    floor = float(np.median(tail)) if len(tail) else 0.0
    useful = np.maximum(power - floor, 0.0)
    useful[0] = 0.0
    total = float(np.sum(useful))
    if not np.isfinite(total) or total <= 1e-14:
        return 0.18
    k = int(np.searchsorted(np.cumsum(useful), 0.94 * total))
    k = min(max(k, 1), bins - 1)
    return float(np.clip(2.0 * k / n, 0.07, 0.28))


def _adaptive_full_record_filter(x):
    """Apply second-order trend filtering with one bounded ADMM solve."""
    x = _finite_signal(x)
    n = len(x)
    if n < 2:
        return x.copy()

    robust = _median3(x)

    # Preserve a strong incumbent reconstruction for short records and failures.
    try:
        if butter is not None and sosfiltfilt is not None and n >= 8:
            cutoff = _spectral_cutoff(robust)
            sos = butter(3, cutoff, btype="lowpass", output="sos")
            padlen = min(3 * (2 * len(sos) + 1), n - 1)
            incumbent = np.asarray(
                sosfiltfilt(sos, robust, padlen=padlen), dtype=float
            )
            incumbent = np.where(np.isfinite(incumbent), incumbent, robust)
        else:
            incumbent = _savgol_safe(robust, 11)
    except Exception:
        incumbent = _savgol_safe(robust, 11)

    if n < 3:
        return incumbent

    try:
        from scipy.linalg import solve_banded

        rho = 2.0
        d = np.diff(robust, 2)
        sigma = _noise_sigma(robust)
        scale = float(np.std(robust))
        if not np.isfinite(scale) or scale <= 1e-12:
            return incumbent

        if not np.isfinite(sigma) or sigma <= 1e-12:
            sigma = 0.15 * scale

        lam = float(np.clip(
            2.2 * sigma * np.sqrt(n),
            0.15 * scale,
            3.5 * scale
        ))

        # Banded representation of I + rho * D2.T @ D2.
        diag = np.full(n, 6.0)
        diag[[0, -1]] = 1.0
        if n > 3:
            diag[[1, -2]] = 5.0
        off1 = np.full(n - 1, -4.0)
        if n > 2:
            off1[[0, -1]] = -2.0
        off2 = np.ones(n - 2)

        ab = np.zeros((5, n), dtype=float)
        ab[2] = 1.0 + rho * diag
        ab[1, 1:] = rho * off1
        ab[3, :-1] = rho * off1
        ab[0, 2:] = rho * off2
        ab[4, :-2] = rho * off2

        def d2_transpose(v):
            out = np.zeros(n, dtype=float)
            out[:-2] += v
            out[1:-1] -= 2.0 * v
            out[2:] += v
            return out

        def shrink(v, threshold):
            return np.sign(v) * np.maximum(np.abs(v) - threshold, 0.0)

        y = np.asarray(incumbent, dtype=float).copy()
        z = np.diff(y, 2)
        u = np.zeros(n - 2, dtype=float)
        threshold = lam / rho

        for _ in range(80):
            rhs = robust + rho * d2_transpose(z - u)
            y_new = np.asarray(
                solve_banded((2, 2), ab, rhs, check_finite=False),
                dtype=float
            )
            if not np.all(np.isfinite(y_new)):
                raise FloatingPointError("non-finite trend solution")

            d2y = np.diff(y_new, 2)
            z_new = shrink(d2y + u, threshold)
            u_new = u + d2y - z_new

            primal = np.linalg.norm(d2y - z_new)
            dual = rho * np.linalg.norm(z_new - z)
            scale_primal = max(
                1.0, np.linalg.norm(d2y), np.linalg.norm(z_new)
            )
            scale_dual = max(1.0, rho * np.linalg.norm(u_new))

            y, z, u = y_new, z_new, u_new
            if (
                primal / scale_primal < 1e-3
                and dual / scale_dual < 1e-3
            ):
                break

        result = 0.90 * y + 0.10 * robust
        return np.where(np.isfinite(result), result, incumbent)
    except Exception:
        return incumbent


def adaptive_filter(x, window_size=20):
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return _adaptive_full_record_filter(x)[window_size - 1:]


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return _adaptive_full_record_filter(x)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    return enhanced_filter_with_trend_preservation(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2.0 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2.0 * t)
        + 0.5 * np.sin(2 * np.pi * 5.0 * t)
        + 0.8 * np.exp(-t / 5.0) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = _finite_signal(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    aligned_clean = clean_signal[window_size - 1:]
    aligned_noisy = noisy_signal[window_size - 1:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
        if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
        else 0.0
    )
    noise_before = np.var(aligned_noisy - aligned_clean)
    noise_after = np.var(filtered_signal - aligned_clean)
    noise_reduction = (
        float((noise_before - noise_after) / noise_before)
        if noise_before > 0 else 0.0
    )

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

